-- PostgreSQL translation of V1__init_schema.sql.
--
-- Dialect notes carried through this whole folder:
--   AUTO_INCREMENT        -> GENERATED BY DEFAULT AS IDENTITY ("BY DEFAULT" not "ALWAYS" so the
--                            V21 seed can insert pinned ids without OVERRIDING SYSTEM VALUE)
--   DATETIME(6)           -> TIMESTAMP(6)
--   DECIMAL(38,2)         -> NUMERIC(38,2)
--   UNIQUE KEY / KEY      -> table-level CONSTRAINT / separate CREATE INDEX
--   ENGINE=InnoDB CHARSET -> dropped (not valid syntax here)

CREATE TABLE IF NOT EXISTS categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    name VARCHAR(255) NOT NULL,
    created_datetime TIMESTAMP(6) NOT NULL,
    updated_datetime TIMESTAMP(6),
    deleted_datetime TIMESTAMP(6),
    CONSTRAINT pk_categories PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS products (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    title VARCHAR(255) NOT NULL,
    description TEXT,
    price NUMERIC(38, 2) NOT NULL,
    category_id BIGINT NOT NULL,
    image VARCHAR(255),
    rating VARCHAR(255),
    created_datetime TIMESTAMP(6) NOT NULL,
    updated_datetime TIMESTAMP(6),
    deleted_datetime TIMESTAMP(6),
    CONSTRAINT pk_products PRIMARY KEY (id),
    CONSTRAINT fk_product_category FOREIGN KEY (category_id) REFERENCES categories (id)
);

CREATE TABLE IF NOT EXISTS orders (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    status SMALLINT,
    created_datetime TIMESTAMP(6) NOT NULL,
    updated_datetime TIMESTAMP(6),
    deleted_datetime TIMESTAMP(6),
    CONSTRAINT pk_orders PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS order_products (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    order_id BIGINT NOT NULL,
    product_id BIGINT NOT NULL,
    quantity INT NOT NULL,
    created_datetime TIMESTAMP(6) NOT NULL,
    updated_datetime TIMESTAMP(6),
    deleted_datetime TIMESTAMP(6),
    CONSTRAINT pk_order_products PRIMARY KEY (id),
    CONSTRAINT fk_order_product FOREIGN KEY (order_id) REFERENCES orders (id),
    CONSTRAINT fk_product_order FOREIGN KEY (product_id) REFERENCES products (id)
);
